-- +goose Up

-- IDs are UUIDv7 strings generated by the application. v7 embeds a millisecond timestamp in its
-- high bits, so ids sort roughly by creation time. That makes the primary key double as the
-- keyset-pagination cursor ("WHERE id > ? ORDER BY id") and keeps b-tree inserts append-mostly.
--
-- Timestamps are TEXT in UTC with a fixed layout (2006-01-02T15:04:05.000Z). SQLite has no
-- native datetime type; fixed-width ISO-8601 text sorts correctly and reads well in a shell.
CREATE TABLE users (
    id            TEXT PRIMARY KEY,
    email         TEXT NOT NULL UNIQUE, -- stored lower-cased by the service
    name          TEXT NOT NULL,
    password_hash TEXT NOT NULL,        -- bcrypt; never the password itself
    created_at    TEXT NOT NULL
);

CREATE TABLE projects (
    id         TEXT PRIMARY KEY,
    owner_id   TEXT NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    name       TEXT NOT NULL,
    created_at TEXT NOT NULL,
    updated_at TEXT NOT NULL,
    UNIQUE (owner_id, name) -- a user cannot have two projects with the same name
);

CREATE TABLE tasks (
    id         TEXT PRIMARY KEY,
    project_id TEXT    NOT NULL REFERENCES projects (id) ON DELETE CASCADE,
    title      TEXT    NOT NULL,
    status     TEXT    NOT NULL DEFAULT 'todo' CHECK (status IN ('todo', 'doing', 'done')),
    priority   INTEGER NOT NULL DEFAULT 3 CHECK (priority BETWEEN 1 AND 5),
    due_date   TEXT,    -- YYYY-MM-DD, NULL = no due date
    created_at TEXT    NOT NULL,
    updated_at TEXT    NOT NULL
);

-- Serves "list tasks of a project, optionally filtered by status, ordered by id" without a sort
-- step: equality columns first, then the ordering column. (project_id alone is a prefix of it, so
-- the FK cascade on project delete uses this index too.)
CREATE INDEX idx_tasks_project_status_id ON tasks (project_id, status, id);

-- +goose Down
DROP INDEX idx_tasks_project_status_id;
DROP TABLE tasks;
DROP TABLE projects;
DROP TABLE users;
